  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "BLU-451, an acrylamide-containing aminopyrimidine EGFR inhibitor, achieved a brain/plasma ratio of 0.62 in intracranial xenograft models, directly demonstrating meaningful CNS access for this acrylamide-pyrimidine chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Poziotinib, an acrylamide covalent inhibitor, showed excellent brain permeability in mice with brain concentrations sustained above its IC50, supporting CNS access for acrylamide warhead compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "GNE-7915, a 5-CF3-2-aminopyrimidine analogue, was brain-penetrant with a CSF/plasma unbound ratio of 0.6 in rat and Cub/Cup of 0.69 in NHP, showing the shared core can achieve good unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Compound 21, a close 5-CF3-2-aminopyrimidine analogue, had a Bu/Pu ratio of 0.70 in rat, directly demonstrating good unbound brain penetration for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A related 5-CF3-2-aminopyrimidine with a morpholine amide had poor Bu/Pu (0.08) in rat, but it lacks the acrylamide warhead and piperazine-acetyl group of the query, so its poor penetration transfers less strongly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Another morpholine-amide analogue had Bu/Pu of 0.11 in rat, but again lacks the query's acrylamide and piperazine-acetyl modifications, limiting transfer of this poor-penetration result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: direct CNS-penetration evidence from acrylamide-containing aminopyrimidine inhibitors (BLU-451, poziotinib) and from the 5-CF3-2-aminopyrimidine core (GNE-7915, compound 21) outweighs poor results in morpholine-amide analogues lacking the acrylamide warhead; the query's acrylamide and N-acetylpiperazine design is consistent with a brain-penetrant covalent EGFR inhibitor.",
  "evidence_gaps": [
    "No direct in vivo brain PK data for the exact query molecule.",
    "No P-gp/BCRP efflux data for the query.",
    "Morgan similarities to the evidence molecules are moderate, not high.",
    "The query's high TPSA and molecular weight remain a passive-diffusion concern."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "acrylamide aminopyrimidine EGFR inhibitor"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C02"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "5-CF3-2-aminopyrimidine"
    }
  ],
  "revision_action": "initial"
}

